// Pixel frames for the interface (9-slice images generated by code, no image file). Pure: RGBA bytes out.
// A frame is a square of `size` pixels made of concentric 1-pixel layers (outer edge first); with `notch` the four corner
// pixels are left empty so the corners look rounded. CSS cuts it with border-image (see styles.css).

import { hx, pack } from './palette.js';

/** layers: array of '#rrggbb' or functions (x, y) => '#rrggbb'. Returns a Uint8ClampedArray size*size*4. */
export function paintFrame(size, layers, notch) {
  const u32 = new Uint32Array(size * size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const d = Math.min(x, y, size - 1 - x, size - 1 - y);
      if (notch && (x === 0 || x === size - 1) && (y === 0 || y === size - 1)) continue;
      let col = layers[Math.min(d, layers.length - 1)];
      if (typeof col === 'function') col = col(x, y);
      const c = hx(col);
      u32[y * size + x] = pack(c[0], c[1], c[2]);
    }
  }
  return new Uint8ClampedArray(u32.buffer);
}

/** The frames of the mock-up: name -> { size, slice, rgba }. */
export const FRAMES = {
  panel: { size: 12, slice: 4, build: () => paintFrame(12, ['#130f2c', '#e9b872', '#4a3d7a', '#2b2358'], true) },
  slot: { size: 9, slice: 3, build: () => paintFrame(9, ['#130f2c', '#3a2f72', '#211a48'], true) },
  btn: { size: 9, slice: 3, build: () => paintFrame(9, ['#2a1c30', '#fff3c4', (x, y) => (y > 5 ? '#e9a85a' : '#ffd27a')], true) },
  btn2: { size: 9, slice: 3, build: () => paintFrame(9, ['#130f2c', '#8a78c8', (x, y) => (y > 5 ? '#2f2760' : '#3d3480')], true) },
};
